{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C21"],
      "claim": "Ergotamine, the closest high-similarity ergopeptine analogue, has absolute oral bioavailability of only 0.9–3.4% after oral tablets in migraine patients, directly supporting low F for the query's ergopeptine scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Ergotamine absolute oral bioavailability is less than 1% versus IV in patients, confirming that ergopeptine alkaloids can undergo near-complete first-pass loss or poor absorption.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Methysergide, an ergoline amide, has systemic availability of only 0.13 ± 0.04 after oral administration, supporting low F for ergot alkaloid derivatives.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Lisuride, an ergoline dopamine agonist, shows low oral bioavailability of 10% ± 7% in humans, consistent with extensive first-pass metabolism in this structural family.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Bromerguride, a brominated ergoline, had oral bioavailability of 29% at 1 mg, slightly above the threshold; however, it lacks the peptide cyclol moiety of the query and is less transferable, providing limited contradictory evidence.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a brominated ergopeptine (bromocriptine-like) containing both an ergoline core and a cyclol peptide. The closest analogue, ergotamine, has extremely low absolute oral bioavailability (<1–5%), and other ergot alkaloids such as methysergide and lisuride also fall below 20%. The only above-threshold brominated analogue, bromerguride, lacks the peptide cyclol and is less transferable. Overall, the evidence strongly supports low oral bioavailability (<20%).",
  "evidence_gaps": [
    "No direct experimental bioavailability record for the query molecule itself is present in the supplied evidence; prediction relies on analogue transfer.",
    "Some ergot alkaloids show dose-dependent and highly variable oral bioavailability, adding quantitative uncertainty despite consistent low-F direction for the closest analogues."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

